case 's':
  if (aColumnName.EqualsLiteral("subjectCol"))
    rv = FetchSubject(msgHdr, m_flags[aRow], aValue);
  else if (aColumnName.EqualsLiteral("senderCol"))
    rv = FetchAuthor(msgHdr, aValue);
